function esc(s) { return String(s); } // use textContent instead

function renderIdeas(ideas) {
  const list = document.getElementById('ideas');
  const empty = document.getElementById('empty');
  list.innerHTML = '';
  if (!ideas.length) { empty.style.display = ''; return; }
  empty.style.display = 'none';
  for (const idea of ideas) {
    const article = document.createElement('article');
    article.className = 'idea';
    const h = document.createElement('h3');
    h.textContent = idea.title;
    article.appendChild(h);
    const desc = document.createElement('p');
    desc.className = 'description';
    desc.textContent = idea.description;
    article.appendChild(desc);
    if (idea.scenario) {
      const sc = document.createElement('p');
      sc.className = 'scenario';
      const strong = document.createElement('strong');
      strong.textContent = '使用场景';
      sc.appendChild(strong);
      sc.appendChild(document.createTextNode('\n' + idea.scenario));
      article.appendChild(sc);
    }
    const meta = document.createElement('p');
    meta.className = 'meta';
    const time = new Date(idea.createdAt);
    meta.textContent = '提交时间：' + (isNaN(time) ? idea.createdAt : time.toLocaleString());
    article.appendChild(meta);
    list.appendChild(article);
  }
}

async function loadIdeas() {
  try {
    const res = await fetch('/api/ideas');
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const data = await res.json();
    renderIdeas(data.ideas || []);
  } catch (e) {
    document.getElementById('empty').textContent = '意见列表加载失败，请稍后重试。';
  }
